package fable.hideseek.imba.net;import fable.hideseek.imba.config.OverlayBarrierConfig;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.network.PacketByteBuf;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.Identifier;public final class OverlayBarrierNetworking{public static final Identifier SYNC=new Identifier("imba","overlay_barriers_sync");private OverlayBarrierNetworking(){}public static void sendSync(ServerPlayerEntity player){PacketByteBuf out=PacketByteBufs.create();var list=OverlayBarrierConfig.snapshot();out.writeVarInt(list.size());for(var e:list){out.writeString(e.world,128);out.writeInt(e.x);out.writeInt(e.y);out.writeInt(e.z);}ServerPlayNetworking.send(player,SYNC,out);}public static void broadcast(MinecraftServer server){for(ServerPlayerEntity player:server.getPlayerManager().getPlayerList())sendSync(player);}}
